 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            objects.append((color, cells))

    def has_hole(cells):
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        occupied = {(r, c) for r, c in cells}
        seen0 = set()
        q = deque()
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if (r in (r0, r1) or c in (c0, c1)) and (r, c) not in occupied:
                    seen0.add((r, c))
                    q.append((r, c))
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if r0 <= p[0] <= r1 and c0 <= p[1] <= c1 and p not in occupied and p not in seen0:
                    seen0.add(p)
                    q.append(p)
        return any((r, c) not in occupied and (r, c) not in seen0
                   for r in range(r0, r1 + 1) for c in range(c0, c1 + 1))

    out = [[0] * w for _ in range(h)]
    occupied = set()
    # Ring-like objects rise; open shapes fall. Within each stream, preserve
    # their vertical order and stop when another packed object blocks them.
    groups = [
        sorted((o for o in objects if has_hole(o[1])), key=lambda o: min(r for r, c in o[1])),
        sorted((o for o in objects if not has_hole(o[1])), key=lambda o: max(r for r, c in o[1]), reverse=True),
    ]
    for group_index, group in enumerate(groups):
        direction = -1 if group_index == 0 else 1
        for color, cells in group:
            shift = 0
            while True:
                nxt = shift + direction
                if any(not (0 <= r + nxt < h) or (r + nxt, c) in occupied for r, c in cells):
                    break
                shift = nxt
            for r, c in cells:
                out[r + shift][c] = color
                occupied.add((r + shift, c))
    return out
